--!strict
local Players=game:GetService("Players");local Shop=require(game:GetService("ReplicatedStorage").Modules.ShopConfig);local Profiles=require(script.Parent.PlayerProfileService);local Service={}
local function container(character:Model):Folder local old=character:FindFirstChild("GameCosmetics");if old then old:Destroy() end;local f=Instance.new("Folder");f.Name="GameCosmetics";f.Parent=character;return f end
function Service.Apply(p:Player) local profile=Profiles.GetProfile(p);local character=p.Character;if not profile or not character then return end;local folder=container(character);local root=character:FindFirstChild("HumanoidRootPart");local head=character:FindFirstChild("Head");for slot,id in profile.Inventory.EquippedCosmetics do if id~="" then local item=Shop.Cosmetics[id];if item then if slot=="Title" and head and head:IsA("BasePart") then local g=Instance.new("BillboardGui");g.Name=slot;g.Size=UDim2.fromScale(4,.6);g.StudsOffset=Vector3.new(0,2.8,0);g.Adornee=head;g.Parent=folder;local t=Instance.new("TextLabel");t.Size=UDim2.fromScale(1,1);t.BackgroundTransparency=1;t.Text=item.DisplayName;t.TextScaled=true;t.TextColor3=Color3.fromRGB(255,220,70);t.Parent=g elseif root and root:IsA("BasePart") then local visual=Instance.new("Part");visual.Name=slot;visual.Size=slot=="BackAccessory" and Vector3.new(2,3,1) or Vector3.new(2.5,.7,2.5);visual.Color=id=="StrawHat" and Color3.fromRGB(235,195,90) or Color3.fromRGB(130,85,45);visual.CanCollide=false;visual.Massless=true;visual.CFrame=root.CFrame*(slot=="BackAccessory" and CFrame.new(0,0,1.2) or CFrame.new(0,2.8,0));visual.Parent=folder;local w=Instance.new("WeldConstraint");w.Part0=visual;w.Part1=root;w.Parent=visual end end end end end
function Service.Equip(p:Player,id:string):(boolean,string) local item=Shop.Cosmetics[id];if not item or not Profiles.OwnsCosmetic(p,id) then return false,"尚未擁有" end;if not Profiles.EquipCosmetic(p,item.Slot,id) then return false,"無法裝備" end;Service.Apply(p);return true,"已裝備" end
function Service.Unequip(p:Player,slot:string):(boolean,string)if not Profiles.UnequipCosmetic(p,slot) then return false,"無效欄位" end;Service.Apply(p);return true,"已卸下" end
Players.PlayerAdded:Connect(function(p)p.CharacterAdded:Connect(function()task.wait(.5);Service.Apply(p)end)end)
return Service
